INSERT INTO `v1_b5dac760a46ea19534c7fcb6627f6b13cb3eb7d8345325bfd253bf4c370158e2` VALUES (21, 6010, "", "", "", "vo_minigame_1013_top_talk_6_001", 0, 6, "", 0, "vo_minigame_1013");
INSERT INTO `v1_b5dac760a46ea19534c7fcb6627f6b13cb3eb7d8345325bfd253bf4c370158e2` VALUES (11, 6011, 0, 0, 0, "マコトさん？\nどうかしましたか？\n何やら不穏な気配を\n感じ取ったのですが", 6, 6, 0.8, 1, 129911);
INSERT INTO `v1_b5dac760a46ea19534c7fcb6627f6b13cb3eb7d8345325bfd253bf4c370158e2` VALUES (91, 6012, "", "", "", "", "", 6, "", "", 0);
