INSERT INTO `v1_b5dac760a46ea19534c7fcb6627f6b13cb3eb7d8345325bfd253bf4c370158e2` VALUES (3, 6014, 0.2, "", 1, "drama_talk_surprise_in_shy", 0, 6, "", "drama_talk_surprise_loop_shy", 129811);
INSERT INTO `v1_b5dac760a46ea19534c7fcb6627f6b13cb3eb7d8345325bfd253bf4c370158e2` VALUES (21, 6015, "", "", "", "vo_minigame_1013_top_talk_6_002", 0, 6, "", 0, "vo_minigame_1013");
INSERT INTO `v1_b5dac760a46ea19534c7fcb6627f6b13cb3eb7d8345325bfd253bf4c370158e2` VALUES (11, 6016, 0, 0, 0, "いやいや何でもない！\nあたしは別に変なこと\n考えてないからな！\nそれより訓練だっ！", 9, 6, 0.3, 1, 129811);
INSERT INTO `v1_b5dac760a46ea19534c7fcb6627f6b13cb3eb7d8345325bfd253bf4c370158e2` VALUES (91, 6017, "", "", "", "", "", 6, "", "", 0);
