INSERT INTO `v1_b5dac760a46ea19534c7fcb6627f6b13cb3eb7d8345325bfd253bf4c370158e2` VALUES (11, 7006, 0, 0, 0, "私の班のみなさんも\n変わらず訓練に励んで\nいるようですわね\n殊勝なことです", 6, 7, 0.3, 1, 129911);
INSERT INTO `v1_b5dac760a46ea19534c7fcb6627f6b13cb3eb7d8345325bfd253bf4c370158e2` VALUES (91, 7007, "", "", "", "", "", 7, "", "", 0);
