INSERT INTO `v1_b5dac760a46ea19534c7fcb6627f6b13cb3eb7d8345325bfd253bf4c370158e2` VALUES (21, 8005, "", "", "", "vo_minigame_1013_top_talk_8_000", 0, 8, "", 0, "vo_minigame_1013");
INSERT INTO `v1_b5dac760a46ea19534c7fcb6627f6b13cb3eb7d8345325bfd253bf4c370158e2` VALUES (11, 8006, 0, 0, 0, "マコト班のみんなも、\nしっかり頑張って\nくれてるみたいだ\n教官としても嬉しいぜ", 7, 8, 0.3, 1, 129811);
INSERT INTO `v1_b5dac760a46ea19534c7fcb6627f6b13cb3eb7d8345325bfd253bf4c370158e2` VALUES (91, 8007, "", "", "", "", "", 8, "", "", 0);
