INSERT INTO `v1_b5dac760a46ea19534c7fcb6627f6b13cb3eb7d8345325bfd253bf4c370158e2` VALUES (21, 8015, "", "", "", "vo_minigame_1013_top_talk_8_002", 0, 8, "", 0, "vo_minigame_1013");
INSERT INTO `v1_b5dac760a46ea19534c7fcb6627f6b13cb3eb7d8345325bfd253bf4c370158e2` VALUES (11, 8016, 0, 0, 0, "くっ、そう言われると\n悔しいな…！\nならこの行軍訓練で\n逆転してやるぜ！", 7, 8, 0.3, 1, 129811);
